module mnist_seg_l50

        #(
            parameter   USER_WIDTH = 0,
            parameter   MAX_X_NUM  = 1024,
            parameter   RAM_TYPE   = "block",
            parameter   DEVICE     = "rtl",
         parameter   S_C  = 32,
         parameter   M_C  = 256,
         parameter   N  = 3,
         parameter   M  = 3,

            parameter   USER_BITS  = USER_WIDTH > 0 ? USER_WIDTH : 1
        )
        (
            input   wire                            reset,
            input   wire                            clk,
            input   wire                            cke,
            
            input   wire                            s_img_line_first,
            input   wire                            s_img_line_last,
            input   wire                            s_img_pixel_first,
            input   wire                            s_img_pixel_last,
            input   wire                            s_img_de,
            input   wire    [USER_BITS-1:0]         s_img_user,
            input   wire    [S_C-1:0]               s_img_data,
            input   wire                            s_img_valid,
            
            output  wire                            m_img_line_first,
            output  wire                            m_img_line_last,
            output  wire                            m_img_pixel_first,
            output  wire                            m_img_pixel_last,
            output  wire                            m_img_de,
            output  wire    [USER_BITS-1:0]         m_img_user,
            output  wire    [M_C-1:0]               m_img_data,
            output  wire                            m_img_valid
        );

    localparam  NC = (N-1) / 2;
    localparam  MC = (M-1) / 2;
    
    
    wire                            img_blk_line_first;
    wire                            img_blk_line_last;
    wire                            img_blk_pixel_first;
    wire                            img_blk_pixel_last;
    wire                            img_blk_de;
    wire    [USER_BITS-1:0]         img_blk_user;
    wire    [N*M*S_C-1:0]           img_blk_data;
    wire                            img_blk_valid;
    
    jelly_img_blk_buffer
            #(
                .USER_WIDTH         (USER_WIDTH),
                .DATA_WIDTH         (S_C),
                .LINE_NUM           (N),
                .PIXEL_NUM          (M),
                .LINE_CENTER        (NC),
                .PIXEL_CENTER       (MC),
                .MAX_X_NUM          (MAX_X_NUM),
                .RAM_TYPE           (RAM_TYPE),
                .BORDER_MODE        ("REPLICATE"),
                .BORDER_VALUE       ({(N*M){1'b0}})
            )
        i_img_blk_buffer
            (
                .reset              (reset),
                .clk                (clk),
                .cke                (cke),
                
                .s_img_line_first   (s_img_line_first),
                .s_img_line_last    (s_img_line_last),
                .s_img_pixel_first  (s_img_pixel_first),
                .s_img_pixel_last   (s_img_pixel_last),
                .s_img_de           (s_img_de),
                .s_img_user         (s_img_user),
                .s_img_data         (s_img_data),
                .s_img_valid        (s_img_valid),
                
                .m_img_line_first   (img_blk_line_first),
                .m_img_line_last    (img_blk_line_last),
                .m_img_pixel_first  (img_blk_pixel_first),
                .m_img_pixel_last   (img_blk_pixel_last),
                .m_img_de           (img_blk_de),
                .m_img_user         (img_blk_user),
                .m_img_data         (img_blk_data),
                .m_img_valid        (img_blk_valid)
            );
    
    genvar                          i, j, k;
    wire    [N*M*S_C-1:0]           img_blk_data_shuffle;
    generate
    for ( i = 0; i < S_C; i = i+1 ) begin : loop_i
        for ( j = 0; j < N; j = j+1 ) begin : loop_j
            for ( k = 0; k < M; k = k+1 ) begin : loop_j
                assign img_blk_data_shuffle[i*(N*M) + j*M + k] = img_blk_data[(j*M + k)*S_C + i];
            end
        end
    end
    endgenerate



	mnist_seg_l50_mlp

            #(
                .USER_WIDTH (USER_BITS + 5),
                .DEVICE     (DEVICE)
            )
        i_mlp
            (
                .reset      (reset),
                .clk        (clk),
                .cke        (cke),
            
                .in_user    ({
                                img_blk_user,
                                img_blk_line_first,
                                img_blk_line_last,
                                img_blk_pixel_first,
                                img_blk_pixel_last,
                                img_blk_de
                            }),
                .in_data    (img_blk_data_shuffle),
                .in_valid   (img_blk_valid),
            
                .out_user   ({
                                m_img_user,
                                m_img_line_first,
                                m_img_line_last,
                                m_img_pixel_first,
                                m_img_pixel_last,
                                m_img_de
                            }),
                .out_data   (m_img_data),
                .out_valid  (m_img_valid)
            );


endmodule


module mnist_seg_l50_mlp
        #(
            parameter USER_WIDTH = 0,
            parameter DEVICE     = "RTL",
            
            parameter USER_BITS  = USER_WIDTH > 0 ? USER_WIDTH : 1
        )
        (
            input  wire                  reset,
            input  wire                  clk,
            input  wire                  cke,
            
            input  wire [USER_BITS-1:0]  in_user,
            input  wire [      288-1:0]  in_data,
            input  wire                  in_valid,
            
            output wire [USER_BITS-1:0]  out_user,
            output wire [      256-1:0]  out_data,
            output wire                  out_valid
        );


reg   [USER_BITS-1:0]  layer0_user;
wire  [      256-1:0]  layer0_data;
reg                    layer0_valid;

mnist_seg_l50_mlp_sub0
        #(
            .DEVICE     (DEVICE)
        )
    i_mnist_seg_l50_mlp_sub0
        (
            .reset      (reset),
            .clk        (clk),
            .cke        (cke),
            
            .in_data    (in_data),
            .out_data   (layer0_data)
         );

always @(posedge clk) begin
    if ( reset ) begin
        layer0_user  <= {USER_BITS{1'bx}};
        layer0_valid <= 1'b0;
    end
    else if ( cke ) begin
        layer0_user  <= in_user;
        layer0_valid <= in_valid;
    end
end


assign out_data  = layer0_data;
assign out_user  = layer0_user;
assign out_valid = layer0_valid;

endmodule




